using System.Numerics;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;

namespace MinMax;

public static class RangeCalculator
{
    /// <summary>
    /// Returns the minimum and maximum values in <paramref name="values"/>.
    /// Uses SIMD vectorization to process multiple elements per iteration.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static (float Min, float Max) FindMinMax(ReadOnlySpan<float> values)
    {
        if (values.Length == 0)
            throw new ArgumentException("Span must not be empty.");

        ref float start = ref MemoryMarshal.GetReference(values);
        int length = values.Length;

        if (!Vector.IsHardwareAccelerated || length < Vector<float>.Count)
        {
            return FindMinMaxScalar(ref start, length);
        }

        int vectorSize = Vector<float>.Count;
        ref float baseRef = ref start;

        var vMin = new Vector<float>(Unsafe.Add(ref baseRef, 0));
        var vMax = vMin;

        // Process two vectors per iteration to improve ILP
        int twoVec = vectorSize * 2;
        int i = vectorSize;
        int limit = length - twoVec + 1;

        for (; i <= limit; i += twoVec)
        {
            var v0 = new Vector<float>(MemoryMarshal.CreateReadOnlySpan(ref Unsafe.Add(ref baseRef, i), vectorSize));
            var v1 = new Vector<float>(MemoryMarshal.CreateReadOnlySpan(ref Unsafe.Add(ref baseRef, i + vectorSize), vectorSize));
            vMin = Vector.Min(vMin, Vector.Min(v0, v1));
            vMax = Vector.Max(vMax, Vector.Max(v0, v1));
        }

        for (; i <= length - vectorSize; i += vectorSize)
        {
            var v = new Vector<float>(MemoryMarshal.CreateReadOnlySpan(ref Unsafe.Add(ref baseRef, i), vectorSize));
            vMin = Vector.Min(vMin, v);
            vMax = Vector.Max(vMax, v);
        }

        // Reduce vector lanes to scalar
        float min = vMin[0];
        float max = vMax[0];
        for (int j = 1; j < vectorSize; j++)
        {
            if (vMin[j] < min) min = vMin[j];
            if (vMax[j] > max) max = vMax[j];
        }

        // Handle remaining elements
        for (; i < length; i++)
        {
            float val = Unsafe.Add(ref baseRef, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }

        return (min, max);
    }

    private static (float Min, float Max) FindMinMaxScalar(ref float start, int length)
    {
        float min = start;
        float max = start;
        for (int i = 1; i < length; i++)
        {
            float val = Unsafe.Add(ref start, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }
        return (min, max);
    }
}

